<div class="page-head"><div><h1>Komunikace</h1><div class="sub">Odpovědi odběratelů na e-maily odeslané přes Byznio se zobrazí tady.</div></div></div><div class="card"><div class="tablewrap"><table class="table"><tr><th>Datum</th><th>Od</th><th>Zákazník</th><th>Předmět</th><th>Doklad</th><th>Zpráva</th></tr><?php foreach($rows as $r): ?><tr><td><?=\App\Core\View::e(date('d.m.Y H:i',strtotime($r['created_at'])))?></td><td><?=\App\Core\View::e($r['from_email'])?></td><td><?=\App\Core\View::e($r['company_name']?:trim(($r['first_name']??'').' '.($r['last_name']??'')))?></td><td><?=\App\Core\View::e($r['subject'])?></td><td><?=\App\Core\View::e($r['doc_number']??'')?></td><td><?=nl2br(\App\Core\View::e($r['body']))?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="sub">Zatím žádné příchozí odpovědi.</td></tr><?php endif; ?></table></div></div>